local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local ContentProvider = game:GetService("ContentProvider")
local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local screenGui = Instance.new("ScreenGui")
screenGui.Name = "TestGui"
screenGui.Parent = playerGui

local function createButton(text, sizeX)
	local button = Instance.new("TextButton")
	button.Name = "ErrorButton"
	button.Text = text
	button.Size = UDim2.new(0, sizeX, 0, 50)
	
	button.AnchorPoint = Vector2.new(0.5, 0)
	button.Position = UDim2.new(0.5, 0, 0, 80)
	
	button.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
	button.TextColor3 = Color3.fromRGB(255, 50, 50)
	button.TextSize = 16
	button.Font = Enum.Font.Code 
	button.Parent = screenGui
	
	local stroke = Instance.new("UIStroke")
	stroke.Color = Color3.fromRGB(180, 0, 0)
	stroke.Thickness = 2
	stroke.Parent = button
	
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 8)
	corner.Parent = button
	
	local dragging, dragInput, dragStart, startPos
	
	button.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = button.Position
			
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)
	
	button.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)
	
	UserInputService.InputChanged:Connect(function(input)
		if input == dragInput and dragging then
			local delta = input.Position - dragStart
			button.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)
	
	return button
end

local viewButton = createButton("[ DO NOT TOUCH ]", 180)

local scareGui = Instance.new("ScreenGui")
scareGui.Name = "JumpScareGui"
scareGui.IgnoreGuiInset = true
scareGui.DisplayOrder = 9999
scareGui.Parent = playerGui

local scareImage = Instance.new("ImageLabel")
scareImage.Name = "ScareImage"
scareImage.Size = UDim2.new(1, 0, 1, 0)
scareImage.Position = UDim2.new(0, 0, 0, 0)
scareImage.BackgroundTransparency = 0
scareImage.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
scareImage.Visible = false
scareImage.Parent = scareGui

local function setupScareImage(imageLabel, rawId)
	task.spawn(function()
		local finalAsset = "rbxassetid://" .. rawId
		
		local success, objects = pcall(function()
			return game:GetObjects(finalAsset)
		end)
		
		if success and objects then
			for _, obj in pairs(objects) do
				if obj:IsA("Decal") or obj:IsA("Texture") then
					finalAsset = obj.Texture
					obj:Destroy()
					break
				end
			end
		end
		
		imageLabel.Image = finalAsset
		
		pcall(function()
			ContentProvider:PreloadAsync({imageLabel})
		end)
	end)
end

setupScareImage(scareImage, "5863569319") 

local scareSound = Instance.new("Sound")
scareSound.Name = "ScareSound"
scareSound.SoundId = "rbxassetid://6754147732"
scareSound.Volume = 0.5
scareSound.Parent = scareGui

local clicked = false

viewButton.MouseButton1Click:Connect(function()
	if clicked then return end
	clicked = true
	
	local tweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In)
	local shrinkTween = TweenService:Create(viewButton, tweenInfo, {
		Size = UDim2.new(0, 0, 0, 0),
		Position = viewButton.Position + UDim2.new(0, viewButton.AbsoluteSize.X/2, 0, viewButton.AbsoluteSize.Y/2)
	})
	shrinkTween:Play()
	
	pcall(function()
		scareSound:Play()
	end)
	
	shrinkTween.Completed:Wait()
	viewButton:Destroy()
	
	task.wait(0.3) 
	
	scareImage.Visible = true
	
	task.wait(1)
	scareImage.Visible = false
end)      
